-- GENERATED by modgen/gen_lua_data.py from the content packs. Do not edit by hand.
return {
  { var = "Quest de_sibling", title = "Errand: Sibling", stages = 2, reward = 500, offer = "Traveller, a small thing. A folded message for someone out among the outlaws. I cannot write the name. They will know it.", objectives = { "Any of them. They will pass it on, or they will not. Say only that it is from home. Then come back and tell me.", "Return and report. It reached them? Thank you. I cannot say how much that means. Take this, and a favour owed" } },
  { var = "Quest de_hum", title = "Errand: Hum", stages = 2, reward = 400, offer = "Would you... if you meet one of the hive, any of them... would you say a thing? I cannot. I do not know how to say it as them.", objectives = { "Tell them... someone out here still counts the days by the hum, though it is not there. Say it exactly. Then come back.", "Return and report. Heard. They said heard. ... I do not know what I feel. It is large. Take these. And a favo" } },
  { var = "Quest de_name", title = "Errand: Name", stages = 2, reward = 600, offer = "A word for the Kingdom. A Shek who still wears his horns, who is not afraid of my name. Will you carry it?", objectives = { "Find a Shek of the Kingdom with his horns. Say: the one with the cut name is alive and has not shamed you again. Do not say where I am. Return.", "Return and report. You said it, and they heard? ... Hrm. A favour owed, /FLATSKIN/. A Shek pays what he owes," } },
  { var = "Quest de_page", title = "Errand: Page", stages = 2, reward = 500, offer = "I should have burned a page. I did not. Will you show it to one of the machine-folk and tell me what they say? Ask them nothing else.", objectives = { "Show it to a skeleton. Ask them what it says, and ask them nothing else. Then come to me. If anyone asks, you found it on a dead man.", "Return and report. Kindness. Of course. ... Thank you. I think I knew. I needed it said by someone who could " } },
  { var = "Quest de_debt", title = "Errand: Debt", stages = 2, reward = 800, offer = "A quiet favour, traveller. Carry word to anyone who works against the slavers, and ask no questions. Tell them a debt is paid in full.", objectives = { "Tell any who work against the slavers that the debt is paid in full. Ask no questions. You never had it from me. Then come back.", "Return and report. They took it? Good. ... I sleep a little better. A favour owed, traveller. Take these." } },
  { var = "Quest hw_q_name", title = "Quiet errand: Name", stages = 2, reward = 400, offer = "Stranger, may I trouble you for a very small thing? A name, carried to another woman. Nothing more. I cannot go myself.", objectives = { "Thank you. Ardis. Say it to a woman, quietly, and tell her it was given in good faith. Then come back. Please.", "Return and report. It arrived? Good. I felt I could breathe a little easier. Here is something for your troub" } },
  { var = "Quest hw_q_bread", title = "Quiet errand: Bread", stages = 2, reward = 300, offer = "Stranger. I have a bowl of bread that someone will not be thanking me for. Will you carry it, and say nothing of where it came from?", objectives = { "Thank you. Find a woman who keeps a shop or works the land, and put it into her hands. She will know what it is. Come back after.", "Return and report. You gave it to her? And she took it? Good. Here, for the bother, and a favour owed. I do n" } },
  { var = "Quest hw_q_phrase", title = "Quiet errand: Phrase", stages = 2, reward = 600, offer = "Stranger, will you say something to a woman for me? Only six words. Some things keep. She will understand, and nobody else will.", objectives = { "Some things keep. Say it low, to a woman who minds a shop or works the land. She will answer, or she will not. Come back and tell me which.", "Return and report. She answered? Then it is working, whatever it is. A little coin for you, and a favour owed" } },
  { var = "Quest hw_q_pilgrim", title = "Quiet errand: Pilgrim", stages = 2, reward = 1000, offer = "Stranger. There is a woman on a pilgrimage who has to pass through before the inspection. Will you tell another woman that the road is quiet?", objectives = { "Thank you. Find a woman who works the shops or the fields and tell her the road is quiet until dusk. She will do the rest. Come back to me after.", "Return and report. She is through? Thank you. No one knew, and no one will. A little coin for you, and a favo" } },
  { var = "Contract ol_orsa_quillon_contract", title = "Bounty: Orsa Quillon", stages = 1, reward = 2400, offer = "A woman strings a rope across the Hub road and calls it a toll. Orsa Quillon. Three caravans have stopped paying her with their lives.", objectives = { "Take guards. She is rarely alone, and she never moves her rope.", "Report back for payment." } },
  { var = "Contract ol_ferrant_dray_contract", title = "Bounty: Ferrant Dray", stages = 1, reward = 3600, offer = "Ferrant Dray was a lordling with a title, an estate and debts. Now he is a highwayman with a title and a sword. The Cities want the title removed, along with the head.", objectives = { "He keeps hired swords near him. And he fights better than he governs. Be careful.", "Report back for payment." } },
  { var = "Contract ol_hask_morrow_contract", title = "Bounty: Hask Morrow", stages = 1, reward = 1900, offer = "A deserter named Hask Morrow walked off his post with his armour and his orders. He now plunders pilgrims on the roads. The Nation wants an example made.", objectives = { "He knows our patrol routes. Do not be where he expects you.", "Report back for payment." } },
  { var = "Contract ol_sarn_ashvael_contract", title = "Bounty: Sarn Ashvael", stages = 1, reward = 1500, offer = "A starving man named Sarn Ashvael preaches that the Empty Bowl will take what the road owes. His mob follows him. Starving men with a prophet are worse than starving men alone.", objectives = { "He and his mob walk the desert and the bone edge. They'll fall on anything that looks fed.", "Report back for payment." } },
  { var = "Contract ol_veldt_harrow_contract", title = "Bounty: Veldt Harrow", stages = 1, reward = 5600, offer = "Veldt Harrow was a slaver. A legal one, if you like. Then the markets thinned and he stopped selling and started burying. They call him the Tallyman. He counts every head he keeps.", objectives = { "He keeps slave hunters with him, men who still think of themselves as honest. They are not.", "Report back for payment." } },
  { var = "Contract ol_borun_vahl_contract", title = "Bounty: Borun Vahl", stages = 1, reward = 4500, offer = "Borun Vahl, the Oathless. He broke his vow in the stone circle and was cast out. He kills those who cross his path, and calls it honour.", objectives = { "He fights without mercy. Do not offer a duel. Do not trust his word.", "Report back for payment." } },
  { var = "Contract ol_ilsa_hearthmourn_contract", title = "Bounty: Ilsa Hearthmourn", stages = 1, reward = 6800, offer = "Ilsa Hearthmourn was a Pacifier of the Flame. She stopped believing and began to pray for the end of Okran. The heresy is spreading. She is spreading it.", objectives = { "She keeps her old armour and her old skills. Do not trust her prayers.", "Report back for payment." } },
  { var = "Contract ol_hodd_crake_contract", title = "Bounty: Hodd Crake", stages = 1, reward = 6200, offer = "Hodd Crake was one of ours. A hunter of the plains. Somewhere out there, he started eating what he killed. He still wears the colours. That shames every hunter alive.", objectives = { "He knows our tricks. He taught half of them. Stay out of the open ground.", "Report back for payment." } },
  { var = "Contract ol_pim_sillery_contract", title = "Bounty: Pim Sillery", stages = 1, reward = 2600, offer = "Pim Sillery was one of us until the day he walked out of a ruin with every schematic and left three hunters in the dark. He calls himself the Magpie. He likes shiny things.", objectives = { "He prowls the ruined fields and the old robot yards. He works with thieves who like his luck.", "Report back for payment." } },
  { var = "Contract ol_teshin_ro_contract", title = "Bounty: Teshin Ro", stages = 1, reward = 4900, offer = "Teshin Ro. A ronin. His lord died, and he has been paying for it ever since. He duels travellers and cuts the ones who refuse. Many dead, last season.", objectives = { "He fights without anger, which is worse. Watch his shoulders. They speak before the sword.", "Report back for payment." } },
  { var = "Contract ol_ysolde_gorehollow_contract", title = "Bounty: Ysolde Gorehollow", stages = 1, reward = 4100, offer = "Ysolde Gorehollow. The Bloodmother. She drains prisoners into jars and sells the contents to anyone sick enough to buy. Her raiders worship it. The Cities want the jars broken.", objectives = { "She keeps a crowd of raiders about her. They love her more than their lives. Plan accordingly.", "Report back for payment." } },
  { var = "Contract ol_marta_cull_contract", title = "Bounty: Marta Cull", stages = 1, reward = 3900, offer = "Marta Cull, the Brine-Wife. She ties salvagers to the tide line and times their drowning. The Guild's coastal runs are dry because of her. Make the sea quiet.", objectives = { "She keeps young Reavers about her. They obey and do not ask. Watch the beaches.", "Report back for payment." } },
  { var = "Contract ol_teodric_clackjaw_contract", title = "Bounty: Teodric Clackjaw", stages = 1, reward = 2800, offer = "Teodric Clackjaw. He fought in the crab pits until he cut an opponent in half after the bell. Banned, he took a shell for armour and a grudge for a god. The Guild wants him quiet.", objectives = { "He and his crabbers wander the pits and the maze. Listen for the clacking.", "Report back for payment." } },
  { var = "Contract ol_maruka_tal_khesh_contract", title = "Bounty: Maruka Tal-Khesh", stages = 1, reward = 5300, offer = "Maruka Tal-Khesh calls herself the Hundred Cuts. She tests every wanderer with a blade, and counts. Few reach ten. The Kingdom does not approve of her excess.", objectives = { "She fights with devotion, and devotion does not tire. Watch the third cut. She prefers the third.", "Report back for payment." } },
  { var = "Contract ol_aldous_peel_contract", title = "Bounty: Aldous Peel", stages = 1, reward = 7200, offer = "Aldous Peel is a skinner in a coat of skins. He takes the living and strips them whole, and wears the work. Some call him the Tailor. The Nation calls him an abomination. I call him a client for you.", objectives = { "He moves in the ash with his tailors. You will see them before you see him. They are very neat.", "Report back for payment." } },
  { var = "Contract ol_mister_tuppence_contract", title = "Bounty: Mister Tuppence", stages = 1, reward = 1800, offer = "Mister Tuppence is a Skeleton who sells road protection. Pay him a fee, and he will not break your cart. Do not pay, and he breaks your cart, and you. It is quite orderly.", objectives = { "He is very polite, and very armed. He will offer you a receipt. Do not sign.", "Report back for payment." } },
  { var = "Contract ol_ulla_weeper_contract", title = "Bounty: Ulla Weeper", stages = 1, reward = 2100, offer = "Ulla Weeper leads the shriekers. She was a mother once, they say, before the swamp took the rest. Now she screams and her followers scream with her, and anything that hears it dies.", objectives = { "Stop your ears if you can. Her mob will come out of the mud before you see them.", "Report back for payment." } },
  { var = "Contract ol_dunmar_quell_contract", title = "Bounty: Dunmar Quell", stages = 1, reward = 5100, offer = "Dunmar Quell calls himself the Red Captain. He has taken over the Red Sabres and means to rule the swamp. Every town in the wet lands pays him now, or does not pay anything again.", objectives = { "His Sabres are loyal, which is rare in a bandit. Be ready for them.", "Report back for payment." } },
  { var = "Contract ol_gammer_tuck_contract", title = "Bounty: Gammer Tuck", stages = 1, reward = 1600, offer = "Gammer Tuck is an old farmer with a long scythe and a longer grudge. He leads rebels who burn tax-collectors. He is usually drunk. He is also quite good with the scythe.", objectives = { "He keeps farmhands with him, more loyal than sensible. Do not underestimate them.", "Report back for payment." } },
  { var = "Contract ol_sayo_of_the_grey_ribbon_contract", title = "Bounty: Sayo of the Grey Ribbon", stages = 1, reward = 4400, offer = "Sayo. The Grey Ribbon. A sand ninja who kills for hire. She leaves a ribbon on the body, and takes the coin from the corpse's pocket. We have eleven ribbons on file.", objectives = { "You will not find her. She will find you. Be ready for the quiet.", "Report back for payment." } },
  { var = "Contract ol_cuddy_pell_contract", title = "Bounty: Cuddy Pell", stages = 1, reward = 1100, offer = "Cuddy Pell. Mad as a flooded fish and twice as slippery. He claims the road is his dinner plate and he sets a place for every traveller. He carries a goat head in a sack. We do not ask.", objectives = { "He is quicker than he looks. Do not trust a smile that wide.", "Report back for payment." } },
  { var = "Contract ol_tchik_of_seven_voices_contract", title = "Bounty: Tchik of Seven Voices", stages = 1, reward = 3000, offer = "Tchik of Seven Voices. A Hiver drone who left the hive and took seven others with him. They speak as one, and they speak to you in seven different voices. Bring them down.", objectives = { "His drones fight as one. Break one and the rest will break with it. Or kill them, worse.", "Report back for payment." } },
  { var = "Contract ol_elric_vosk_contract", title = "Bounty: Elric Vosk", stages = 1, reward = 2600, offer = "Elric Vosk was hired to guard a caravan. His employer cut his pay. He killed the master, the drivers and the pack-beasts, and kept the bell. Now he sells the road he once guarded.", objectives = { "He will meet you politely, as a guard would. He is expecting to be asked for work.", "Report back for payment." } },
  { var = "Contract ol_pyke_ludlow_contract", title = "Bounty: Pyke Ludlow", stages = 1, reward = 3800, offer = "Pyke Ludlow was an Anti-Slaver. A true one. Then he decided that anyone who ever owned or traded a person deserved the same, and began killing them. Merchants. Farmers. A boy who sold a rope.", objectives = { "He is excellent in a fight and will not hear your side. Do not try.", "Report back for payment." } },
  { var = "Quest qc_caravan", title = "Work: Caravan", stages = 2, reward = 8000, offer = "A caravan bound for a Shek town never arrived. The Guild keeps its word. Carry the factor four iron plates, then deal with whoever took the rest.", objectives = { "Bring four iron plates to a Shek shopkeeper. He will know the delivery. Then see to Elric Vosk and come back to me.", "Return and report. Vosk is dead? Then the wagons are paid for, one way or another. The Guild thanks you. Here" } },
  { var = "Quest qc_hunt", title = "Work: Hunt", stages = 2, reward = 16000, offer = "The nightmares never go away. There is a Meat Lord out in the plains. I will not send you without proof you can kill one of them.", objectives = { "A severed arm from the painted ones. Right hand will do. Bring it to a hunter, any hunter. Then the Meat Lord.", "Return and report. The Meat Lord is dead. The nightmares will not end, but they have lost a teller. Take the " } },
  { var = "Quest qc_relic", title = "Work: Relic", stages = 2, reward = 26000, offer = "The University wants Rhinobot's CPU. Rhinobot wanted to help and had no moral processing. We would like to study what is left of him.", objectives = { "Finch will tell you what he needs. Bring Rhinobot's CPU to his assistant Iyo. Iyo handles the pay.", "Return and report. Rhinobot's core. Intact. Finch will be insufferable. The University pays. Here." } },
  { var = "Quest qc_slaver_hire", title = "Work: Slaver Hire", stages = 2, reward = 7000, offer = "An ex-Anti-Slaver is bleeding our wagons. Pyke Ludlow. We pay for his end. First the pens need dressings: two medical supplies to the slave shop.", objectives = { "Two medical supplies to a slave shop trader. Then Pyke Ludlow. Come back when he is dead.", "Return and report. Ludlow is dead. The wagons will travel in peace for a month. Here is your pay." } },
  { var = "Quest qc_inquisition", title = "Work: Inquisition", stages = 3, reward = 9000, offer = "There is rot in the Flame's own household. Ilsa Hearthmourn wore our colours once. Now a cell shelters her, and the Nation must follow its threads.", objectives = { "Begin with the priests. Confession leaves marks. After them, the Paladins on the roads. Find her, end her, and return to me.", "The Paladins on the roads have seen their cell moving. Ask them where. I have said too much already.", "Return and report. Hearthmourn is dead? Then her cell will wither. The Flame is grateful, and so is the Inqui" } },
  { var = "Quest qc_tipoff", title = "Work: Tipoff", stages = 2, reward = 15000, offer = "A man crawled out of a slave farm last week, half dead, with a name on his lips. The ones who got away know more than we do. Ask them.", objectives = { "Find an escaped slave. Any camp, any road. They will tell you where Grace works. Then end her.", "Return and report. Grace is dead? The farm is open? The Anti-Slavers pay what they owe. It is little for a th" } },
  { var = "Quest qc_duel", title = "Work: Duel", stages = 2, reward = 14000, offer = "Tora was one of us. The Stone Golem took her horns and she kept her blade. A warrior who will not put down her sword must be answered with one.", objectives = { "Speak to the warriors at the gates first. They will give you the terms. One blade, no tricks, no run.", "Return and report. Tora is dead. She met the blade as a warrior should. The Kingdom marks your name." } },
  { var = "Quest qc_rebel_farm", title = "Work: Rebel Farm", stages = 2, reward = 18000, offer = "Boss Simion has the Rebel Farmers behind a palisade and a long list of Empire fields burned. The Cities want the head, not the farm.", objectives = { "Find a loyal farmer of the Empire. They will tell you what they know. Then Simion, and then me.", "Return and report. Simion is dead? The Cities thank you and pay promptly. The fields will be quiet by autumn." } },
  { var = "Quest qc_red_bandit", title = "Work: Red Bandit", stages = 2, reward = 11000, offer = "The Red Sabre boss sits in his hideout with a score of blades and takes a cut of every cart through the wet. We want him out of the mud.", objectives = { "Ask at a swamper bar. Barmen hear what the bandits boast of. Then walk in and end him.", "Return and report. The Red Sabre boss is dead? The wet breathes easier. Here are the swamp's cats." } },
  { var = "Quest qc_skeleton_bounty", title = "Work: Skeleton Bounty", stages = 2, reward = 28000, offer = "The University studies Skeletons. The Elder preaches against flesh, and his followers prey on travellers. He is a data point we can no longer afford.", objectives = { "Find a Skeleton in one of the towns. They know the Elder's creed. Then you will know where he waits.", "Return and report. The Elder is dead. The University is grateful and the Skeletons are quieter. Here is the p" } },
  { var = "Quest qc_savant", title = "Work: Savant", stages = 2, reward = 60000, offer = "The Skin Bandits wear their victims. Their master, Savant, has a bounty on him the size of a small city. The Cities want him gone.", objectives = { "Find a bounty hunter. They know the cost of failing. Then kill Savant and return to me.", "Return and report. Savant is dead? The Cities have waited years. Here is more than a soldier earns in a lifet" } },
  { var = "Quest qc_dust_king", title = "Work: Dust King", stages = 2, reward = 24000, offer = "The Dust King holds the dry roads with more men than the Guild can field. Speak to the mercenaries who have walked them, then take the contract.", objectives = { "Find a sellsword who has been out there. They will tell you what the walls are like. Then end him.", "Return and report. The Dust King is dead. The Guild has waited a long time for this. Here is the pay." } },
  { var = "Quest qc_hive_drone", title = "Work: Hive Drone", stages = 2, reward = 5500, offer = "One of us left. He took seven others. They speak with seven voices and none of them are ours. This is a wound.", objectives = { "The workers hear much. Listen to them. Then find Tchik and end the question.", "Return and report. He is quiet now. The Hive feels it. A warm place where a cold one was. We thank you." } },
  { var = "Quest iq_road", title = "Investigation: Road", stages = 5, reward = 12000, offer = "Two of ours walked the east road to market and never arrived. No bodies, no carts, no word. It is the third time this month.", objectives = { "Ask the Guild's wagon drivers, then the drifters who camp off the road. Somebody saw a lantern or a cart. Come back with a name.", "The drivers will not look at him. Ask the drifters who camp near there. They count the faces that pass.", "Toward the flats, where the ground is soft. I did not follow. The Anti-Slavers did, once, and lost two.", "Ask the slavers. He was theirs once. They will not like it, but they know where his road runs.", "Return and report. The Tallyman is dead? Then the road is only a road again. Take this. It is the village's t" } },
  { var = "Quest iq_inquisitor", title = "Investigation: Inquisitor", stages = 5, reward = 8500, offer = "An Inquisitor rode north after a runaway from Rebirth. He did not write and he did not return. The Nation would know what ate him.", objectives = { "Begin at a gate. Guards log who goes out. Then the farmers on the northern fields, then a priest. Report when you know.", "Ask the farmers on the northern fields. They sell to anyone who walks that road.", "I do not know his name. Ask a priest. A deserter's name is whispered in confession before it is spoken anywhere else.", "Okran's Pride, near the roads the pilgrims use. Ask a pilgrim who has been robbed. They count themselves lucky to be alive.", "Return and report. Morrow is dead? And the cloak? Then the Inquisitor will not be found, and the Nation will " } },
  { var = "Quest iq_shore", title = "Investigation: Shore", stages = 5, reward = 13000, offer = "A convoy ended on the south shore. The drivers were found at the tide line and the cargo was gone. Someone took their time over it.", objectives = { "Ask the shore folk who found them. Then the Mercenary Guild, who sold the guards. Then the Guild clerks who filed the route.", "Two mercenaries went with them. Neither was on the sand. Ask the Mercenary Guild.", "The Traders Guild filed it. Ask them who handled the paper. They will not like the question.", "Ask someone who walks the coast. The Red Coast, the Old Beach, the Old Pits. A drifter will know where her people sit.", "Return and report. The Brine-Wife is dead? Then the tide is only the tide again. Take this. It is what the co" } },
  { var = "Quest iq_talker", title = "Investigation: Talker", stages = 5, reward = 8500, offer = "There is a Skeleton that will not stop talking. It says a sum, a road and a count, over and over. Something was done to it. Find who.", objectives = { "It says a sum, then a road, then a count. Ask the traders who use roads, and a repairer who reads memory cells. Return when you know the speaker.", "A repairer would know the loop. Ask the Tech Hunters. They keep a bench for that kind of work.", "A Skeleton town would know who is missing a collector. Ask the barman. They hear everything.", "The old pits and the robot graveyard. He charges a penny a cart. He keeps the rest.", "Return and report. Tuppence is closed? Then the talker will stop. Or it will not, but it will have an ending." } },
  { var = "Quest iq_machines", title = "Investigation: Machines", stages = 5, reward = 40000, offer = "Old machines walk in the Ashlands. Not wandering. Walking, in one direction. I would like to know who is calling them.", objectives = { "Tech Hunters see machines more than anyone. Ask them. Then the Hive, who built the limbs. Then the old Skeletons, who remember him.", "Ask someone who knows the old workshops. The Hive made the first limbs. They will know a signal when they see one.", "Ask the old Skeletons. They remember who spoke so. I will not say the name.", "The domes in the Ashlands. A throne and a few who still answer. Ask the Machinists. They have the maps.", "Return and report. Cat-Lon is silent. The machines have stopped walking. It took a thousand years to get here" } },
  { var = "Quest iq_tinfist", title = "Investigation: Tinfist", stages = 5, reward = 45000, offer = "I have followed Tinfist's raids for a year. They come wider and wilder. A man like that wants a loud ending. I mean to give him a quiet one. Do you?", objectives = { "Start with the Cities' scouts. They count patrols. Then the slavers he hits. Then the old Skeletons who knew him. Report to a hunter, any hunter.", "Ask the slavers who bear the raids. They know which roads he skips. Those roads are where he sleeps.", "Ask the old Skeletons in the Black Desert. They knew him before he was a terror.", "He sleeps in the Anti-Slavers' own city. Grey sits at his side. Ask a Traders Guild man. They know where the raids start.", "Return and report. Tinfist is dead? The largest bounty on the continent, and a quiet hunter ended it. The Cit" } },
  { var = "Quest iq_domes", title = "Investigation: Domes", stages = 5, reward = 36000, offer = "I study the old failures. The domes failed in an order: the harvest, the police, the cult. I want the first failure told by someone who was there.", objectives = { "Ask the Tech Hunters who have walked the domes. Ask the Machinists, who keep the old records. Then the Skeletons who remember. Bring him alive.", "The Machinists read the old Empire records. Ask Finch or Iyo. They would want to know a clerk still lives.", "Ask the old Skeletons what they remember of the thralls. They guarded what the Empire valued.", "The first dome in the Ashlands. A cage will serve. He will not resist. He has forgotten how.", "Return and report. The Head of Agriculture is in custody? Then the record can begin. Alive. That is more than" } },
  { var = "Quest iq_fog", title = "Investigation: Fog", stages = 5, reward = 18000, offer = "The Fogmen take the living, not the dead. That is not hunger. That is habit. Someone should ask why before the next one is carried off.", objectives = { "Ask the town. Ask the Fishers, who sail near the isles. Ask the Hive, who know what the Fogmen were. Then find the one at the heart.", "The Fishers sail close to the isles. Ask them what stands on the shore.", "The Hive know what the Fogmen were. They will not like being asked. Ask a worker.", "Seek a Prince. A Prince is the heart of the pack. Break it and the rest fray.", "Return and report. The Prince is dead? The fog is a little thinner. They will not carry any more of ours, for" } },
  { var = "Quest iq_rebirth", title = "Investigation: Rebirth", stages = 5, reward = 16000, offer = "My sister was in Rebirth. She got out. A woman in dyed robes does not go unseen. I heard she went toward the ash. Help me find her.", objectives = { "Ask the Anti-Slavers who take in the runaways. Then the road folk. Then the scavengers at the edge of the ash. Someone saw a robe.", "Ask the drifters who camp along the edge. They watch who goes in.", "Tech Hunters work the ash edge. They go in and out. Ask them what they found.", "The Holy Nation knows the thing in the coat. They will not tell scavengers. Ask a Paladin.", "Return and report. Peel is dead? Then she is not in the ash anymore. She is only in the ground. I thank you. " } },
  { var = "Quest rc_venna_q", title = "Recruit: Venna", stages = 2, reward = 3000, offer = "Anti-Slavers keep a list of names, and one name keeps coming back. Orrin Vask runs the floodwaters. A woman with a scarf has been asking about him. Is she yours?", objectives = { "Ask a Swamper in the town. They know his boats. Then end Vask and come to me.", "Return and report. Vask is dead? Then somebody's wife sleeps tonight. The Anti-Slavers thank you. Here are th" } },
  { var = "Quest rc_corvin_q", title = "Recruit: Corvin", stages = 2, reward = 2800, offer = "A former sergeant in your squad has been asking about Aldric Roane. That name is poison here. Roane sold a gate and left a man holding the blame.", objectives = { "Ask the Traders Guild who bought Roane's stolen gate. The wagon men know. Then finish him.", "Return and report. Roane is dead. Then the Flame is a little cleaner. Here is coin from an honest man." } },
  { var = "Quest rc_dova_q", title = "Recruit: Dova", stages = 2, reward = 3200, offer = "A Shek with you has been asking after Karrash Red-Hand. We know the name. He took a southern post and left no one to bury. Find him, flatskin.", objectives = { "Ask the shopkeepers in our towns. They hear what riders say. Then find the Berserker and finish it.", "Return and report. Red-Hand is dead. The Kingdom is a little safer. Take the cats, flatskin." } },
  { var = "Quest rc_lull_q", title = "Recruit: Lull", stages = 2, reward = 2600, offer = "A quiet one among your company has been asking about Veth of the Closed Hand. We have heard of him. He leads those who were sent out, and they follow him.", objectives = { "Speak to the Tech Hunters. They watch the Dark Fingers. They will know where Veth makes his camp.", "Return and report. Veth is gone? The hive will not mourn. Take the cats. We hope the quiet one sleeps better." } },
  { var = "Quest rc_spindle_q", title = "Recruit: Spindle", stages = 2, reward = 2400, offer = "Observation. A tinkerer in your company is looking for Hollis Gantry. He is a Tech Hunter who sells our dead for parts. We would like him disabled.", objectives = { "Ask the Tech Hunters about their ruin crews. Gantry once worked for them. Then find him in the Graveyard.", "Return and report. Gantry is disabled. The Skeletons note your service. Take the payment." } },
  { var = "Quest rc_hale_q", title = "Recruit: Hale", stages = 2, reward = 3000, offer = "Gaffer Marrowbone is a name the Hunters spit. He took a hunting party at dinner. A survivor travels with you, I am told. We pay for his end.", objectives = { "Ask the Deadcat fishermen. They hear the cannibals' stories from the water. Then go to the badlands.", "Return and report. Marrowbone is dead? Then the plains are a little safer. The Hunters pay. Here." } },
  { var = "Quest rc_mara_q", title = "Recruit: Mara", stages = 2, reward = 2800, offer = "The Guild keeps its records. A caravan of ours did not arrive on the dust road. A Scorchlander with you may know the details. Rennik Salt took it, and we want him.", objectives = { "Ask a United Cities guard about the dust road. They keep a map of raids. Then find Salt in the hills.", "Return and report. Salt is dead? The Guild is relieved. The dust road is a little safer. Your payment." } },
  { var = "Quest rc_marn_q", title = "Recruit: Marn", stages = 2, reward = 2800, offer = "A Tech Hunter in your company has a score with Slate Fennick. We have a score too. He sells stolen finds. Help us end him.", objectives = { "Ask the Mercenary Guild where Fennick drinks. They hire swords like his. Then deal with him.", "Return and report. Fennick is dead? A thief fewer. The Hunters pay. Here is your share." } },
  { var = "Quest rc_dace_q", title = "Recruit: Dace", stages = 2, reward = 2600, offer = "A former overseer travels with you. He wants Brannoch Teel. So do we. Teel hunts our runaways on the floodwaters. Finish him.", objectives = { "Ask the Slave Traders. Their men talk when coin is shown. Then the floodwaters.", "Return and report. Teel is dead? The Swamp breathes easier. Here is the payment." } },
  { var = "Quest rc_marelle_q", title = "Recruit: Marelle", stages = 2, reward = 1800, offer = "A medic in your company has been asking after Hob Lenner. I bought a field kit off him once and found blood in the lining. I would be glad to see him ended.", objectives = { "Ask the United Cities guard about Reaver camps on the coast. Then find Lenner.", "Return and report. Lenner is dead? Then the kits on my shelf are the last he sold. Here is the payment." } },
  { var = "Quest rc_nub_q", title = "Recruit: Nub", stages = 2, reward = 1800, offer = "A worker in your company has asked about Dolan Pike. We know him. He leads hungry men. He burned a hive. We cannot forgive.", objectives = { "Ask a City guard about the hungry bandits. They keep a record. Then find Pike in the dry edge.", "Return and report. Pike is dead? The hungry will be quieter. Here is the payment." } },
  { var = "Quest rc_wren_q", title = "Recruit: Wren", stages = 2, reward = 2800, offer = "One of our own travels with you. She has been asking about Isolde Marr. We know the name. She sold a cell and stayed free. Remove her.", objectives = { "Ask the free traders where mercenaries drink. They sell to everyone. Then find Marr.", "Return and report. Marr is dead? The village will sleep better. Here is the payment." } },
  { var = "Quest cr_cord", title = "Courier: Cord", stages = 2, reward = 600, offer = "Stranger. I have a cord, and every knot in it is a name. I cannot give it to anyone here and I cannot burn it. Will you take it past the walls?", objectives = { "Here. Anyone who stands against the slavers. Say it is from inside and do not say whose hand. Then come back and tell me it was taken.", "Return and report. They took it? Then it is out of my hands. Here, this coat was put aside for something else" } },
  { var = "Quest cr_tally", title = "Courier: Tally", stages = 2, reward = 500, offer = "Stranger. I keep count of days. It is all I keep. Take the count to the hive. They will know what it is.", objectives = { "Here. Any of the hive. They will understand rows of cuts. Say it is from one outside. Then come back and say it was held.", "Return and report. Held. I did not expect them to say it. Take these. And a favour, if I can ever give you on" } },
  { var = "Quest cr_hide", title = "Courier: Hide", stages = 2, reward = 700, offer = "/FLATSKIN/. I have a thing the Kingdom should have back. I cannot carry it there. You can.", objectives = { "Here. A Shek of the Kingdom, any who will take it. Say nothing of me but that it is returned. Then come back.", "Return and report. Taken, and nothing said. Good. Take these. A Shek pays what he owes, even from a long way " } },
  { var = "Quest cr_page", title = "Courier: Page", stages = 2, reward = 800, offer = "I took a page off a dead man in the ruins. Old script, I cannot read it. A skeleton can. Take it, tell me what it says.", objectives = { "Here. Any skeleton who will read. Ask what it says and nothing else. Skeletons talk plain. Come back.", "Return and report. You got it read. Good. I will not ask what it said, your face told me enough. Take the cat" } },
  { var = "Quest cr_coin", title = "Courier: Coin", stages = 2, reward = 900, offer = "I have a coin that does not belong to me anymore. There are people who undo my trade. Take it to them. Do not say whose.", objectives = { "Here. Any of them that free slaves. Say the debt is paid. Say nothing else. Come back and tell me it was taken.", "Return and report. Taken. Not forgiven, I would guess. Good. Cats for your trouble." } },
  { var = "Quest cr_note", title = "Courier: Note", stages = 2, reward = 400, offer = "I have a note for my brother. He took up with a rough crowd. Mongrel, last I heard. I cannot go. Would you put it in someone's hand there?", objectives = { "Here. No name. They will pass it among themselves, or they will not. Say it is from family. Come back and tell me.", "Return and report. They took it. Thank you. I did not know if anyone would. Here is some coin, and my father'" } },
}
